              <Eyebrow hint={`${t.repartition_marque_hint} · ${dateRangeLabel} (${periodStats.from} → ${periodStats.to})`}>{globalMp === "Toutes" ? `${t.repartition_marque} — ${t.toutes_marketplaces_suffix}` : `${t.repartition_marque} — ${globalMp}`}</Eyebrow>
