                                    {PRODUCT_CATALOG[p.produit].connecte && <span className="text-[8.5px] px-1.5 py-0.5 rounded-full font-semibold" style={{ background: `#4A9EFF18`, color: "#4A9EFF" }}>{t.pd_connecte_wifi}</span>}
